          <div className="reading-primary-actions">{__YOHAKU_BOOK_DESIGN__&&<><select className="reader-display-select" aria-label="教材の表示方法" value={text?'web':pdfLayout} onChange={e=>{closeTools();if(e.target.value==='web')setText(true);else{setText(false);setPdfLayout(e.target.value as PdfLayout);}}}><option value="web">Web本文</option><option value="single">PDF 1ページ</option><option value="spread">PDF 見開き</option></select><button className="button small reader-fullscreen-direct" aria-label={fullscreen?'通常表示に戻る':'全画面で読む'} title={fullscreen?'通常表示に戻る':'全画面で読む'} onClick={()=>{closeTools();if(fullscreen&&!nativeFullscreen)leaveExpanded();else{if(!fullscreen)setZoom(1);toggleFullscreen();}}}>{fullscreen?<Minimize size={17}/>:<Maximize size={17}/>}<span className="reader-fullscreen-caption">{fullscreen?'通常表示':'全画面'}</span></button></>}<button className={'button small '+(memoOpen?'is-saved':'')} ref={memoToggle} aria-controls="page-note-panel" aria-expanded={memoOpen} onClick={toggleMemo}><NotebookPen size={17}/>{dirty?'補足（未保存）':ready&&saved?'補足を見る':'補足を書く'}</button><button ref={toolToggle} className={'button small reader-tools-toggle '+(toolsOpen?'is-saved':'')} aria-controls="reader-tools-panel" aria-expanded={toolsOpen} onClick={()=>setToolsOpen(!toolsOpen)}><SlidersHorizontal size={17}/>ツール</button></div>
