function UploadDialog({close,done,duplicate}:{close:()=>void;done:(b:Book)=>void;duplicate:(b:Book)=>void}){
  const [file,setFile]=useState<File|null>(null),[title,setTitle]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[progress,setProgress]=useState('');const dialog=useRef<HTMLDivElement>(null),fileInput=useRef<HTMLInputElement>(null);
  const busyRef=useRef(false);busyRef.current=busy;
  useEffect(()=>{const prev=document.activeElement as HTMLElement;dialog.current?.focus();const handle=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busyRef.current)close();if(e.key==='Tab'){const els=Array.from(dialog.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), [href]')||[]).filter(e=>e.getClientRects().length);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};window.addEventListener('keydown',handle);return()=>{window.removeEventListener('keydown',handle);prev?.focus();};},[]);
  function choose(f:File|undefined){setError('');if(!f)return;if(!f.name.toLowerCase().endsWith('.pdf')||f.size>20*1024*1024||!f.size){setFile(null);setError('20MB以内のPDFファイルを選んでください。');return;}setFile(f);setTitle(f.name.replace(/\.pdf$/i,'').replace(/_/g,' '));}
  async function submit(e:React.FormEvent){e.preventDefault();if(!file||!title.trim())return;setBusy(true);setError('');let doc:any;
    try{setProgress('PDFを読み取っています…');const lib=await pdfLibrary();doc=await lib.getDocument({...pdfOptions,data:new Uint8Array(await file.arrayBuffer()),password:''}).promise;
      if(doc.numPages>1000)throw new Error('1,000ページまでの教材を追加できます。');
      const labels=await doc.getPageLabels(),pages=[];
      for(let i=1;i<=doc.numPages;i++){setProgress(`文字を読み取っています ${i} / ${doc.numPages} ページ`);const page=await doc.getPage(i),text=await page.getTextContent();const content=text.items.map((t:any)=>t.str+(t.hasEOL?'\n':' ')).join('');const footer=content.match(/(本文|元)\s*(\d+)\s*\/\s*PDF/);pages.push({label:footer?footer[1]+' '+footer[2]:labels?.[i-1]||String(i),content});}
      if(!pages.some(p=>p.content.trim()))throw new Error('文字を抽出できません。画像だけのPDFは文字認識（OCR）後に追加してください。');
      setProgress('教材と検索用の文字を保存しています…');const form=new FormData();form.append('file',file);form.append('title',title.trim());form.append('pages',JSON.stringify(pages));const result=await api('upload',{method:'POST',body:form});result.duplicate?duplicate(result.book):done(result.book);
    }catch(e){const err=e as Error;setError(err.name==='PasswordException'?'パスワード保護されたPDFには対応していません。保護を解除したPDFを追加してください。':err.message||'PDFを読み取れませんでした。');}finally{doc?.destroy();setBusy(false);}}
  return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget&&!busy)close();}}><div className="upload-dialog" role="dialog" aria-modal="true" aria-labelledby="upload-heading" tabIndex={-1} ref={dialog}><div className="dialog-top"><span className="dialog-icon"><BookOpen size={23}/></span><button className="icon-button" aria-label="閉じる" onClick={close} disabled={busy}><X size={20}/></button></div><h2 id="upload-heading">新しい学びを、本棚へ。</h2><p className="muted">PDFを追加すると、ほかの教材や補足と一緒に検索できます。</p><form onSubmit={submit}><input ref={fileInput} id="pdf-file" className="sr-only" type="file" accept="application/pdf,.pdf" disabled={busy} aria-label="追加するPDF" onChange={e=>choose(e.target.files?.[0])}/><button type="button" disabled={busy} className={'drop-zone '+(file?'has-file':'')} onClick={()=>fileInput.current?.click()} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();if(!busy)choose(e.dataTransfer.files[0]);}}>{file?<FileText size={28}/>:<Upload size={28}/>}<strong>{file?file.name:'PDFを選択、またはここにドロップ'}</strong><span>{file?size(file.size):'20MBまで · 1,000ページまで'}</span></button><label className="field-label" htmlFor="book-title">教材のタイトル</label><input className="title-input" id="book-title" value={title} maxLength={120} disabled={busy} required placeholder="例：Unreal C++ 第2巻" onChange={e=>setTitle(e.target.value)}/>{error&&<Notice>{error}</Notice>}{busy&&<div className="upload-progress" role="status"><Spinner/>{progress}</div>}<p className="upload-footnote">文字を含むPDFに対応しています。画像だけのPDFはOCR後に追加してください。紙面番号はPDFのページラベルを使い、ない場合はPDFページ番号を表示します。</p><button className="button primary full" type="submit" disabled={!file||!title.trim()||busy}>{busy?<Spinner/>:<Plus size={17}/>}本棚に追加する</button></form></div></div>;
}

